					Stream.of(referenceChunk)
			).toList();
			// @formatter:on
			var chatCompletionMessage = new ChatCompletionMessage(contentChunks, Role.ASSISTANT);
			assertThat(chatCompletionMessage.extractReferenceContent()).containsExactly(1, 2, 3, 4, 5, 6);
		}

	}

