			assertThat(chatCompletionMessage.extractThinkingTextContent()).isNull();
		}

		@Test
		void extractContentChunksContentHavingEmptyThinkingTextContentChunks() {
			List<ThinkingContentChunk> thinkingContentChunks = List.of();
